window.MG_LAZY_DATA["data/lazy/owner-courses/d401-0a31a90bec47d924.json"]={sha256:"0a31a90bec47d924ba8a350d56011690cb2b8422b8c71aa03b23f6588342eed3",value:{"id":"d401","title":"大型強子對撞機LHC","titleEn":"Large Hadron Collider LHC","category":"megascience","kind":"course","summary":"以 LHC 的公開系統介紹拆解束流導引、RF、低溫、真空與探測資料介面。","summaryEn":"Use public LHC system descriptions to examine beam guidance, RF, cryogenics, vacuum and detector-data interfaces.","scope":"十二步是紙上模型與原創示意圖的概念課程，不提供真實機器設定、束流操作、聯鎖解除或繞過方式。教學事件卡不是真實 LHC 量測，也不作新物理結論；不是加速器設計或運轉 SOP。","scopeEn":"Twelve tasks use paper models and original concept diagrams. They provide no real machine settings, beam operations, interlock releases or bypass methods. Teaching event cards are not LHC measurements and support no new-physics conclusions; this is not an accelerator design or operating SOP.","contentStatus":"reviewable-educational-curriculum","sourceIds":["v6-science-lhc","v6-science-lhc-magnets","v6-science-lhc-rf","v6-video-6UqW4GEla3Q"],"depth":4,"diagram":{"type":"megascience","labels":["束流","磁鐵","RF 共振腔","低溫／真空","探測與資料"],"labelsEn":["Beam","Magnets","RF cavities","Cryogenics / vacuum","Detection and data"],"original":true,"notToScale":true},"stages":[{"id":"d401-stage01","order":1,"title":"職責與束流幾何","titleEn":"Responsibilities and beam geometry","description":"區分加速器、探測器、束團與彎轉。","descriptionEn":"Distinguish accelerator, detector, bunches and bending.","route":"依學習相依關係閱讀；這四步是公開原理的概念任務，不是現場施工、操作或量產程序。","routeEn":"Follow the learning dependencies. These four tasks explore public principles; they are not field, operating or production procedures.","steps":[{"id":"d401-v6-01","order":1,"sequence":1,"prerequisiteIds":[],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-lhc"],"title":"分開加速器與探測器職責","titleEn":"Separate accelerator and detector responsibilities","objective":"辨識導引加速束流與記錄碰撞的不同系統。","objectiveEn":"Distinguish systems that guide and accelerate beams from systems that record collisions.","instruction":"把磁鐵導引、射頻加速、真空保持放入加速器欄；把碰撞訊號與事件紀錄放入探測器欄，畫交會介面。","instructionEn":"Place magnetic guidance, RF acceleration and vacuum maintenance under accelerator; place collision signals and event records under detector and draw their interface.","observation":"加速器與探測器緊密協作，但交付內容不同。","observationEn":"Accelerator and detector cooperate closely but deliver different functions.","failure":"把所有設備都稱作探測器，會隱藏束流條件與量測的分工。","failureEn":"Calling every component a detector hides the distinction between beam conditions and measurements.","check":"每張卡都有主責系統，並標示碰撞點的共同介面。","checkEn":"Assign a primary system to every card and mark the shared collision-point interface.","knowledge":[{"id":"d401-v6-01-k1","title":"工程原理","titleEn":"Engineering principle","text":"加速器建立粒子束條件；探測器把相互作用轉為可分析訊號。","textEn":"Accelerators establish beam conditions; detectors turn interactions into analyzable signals."},{"id":"d401-v6-01-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"本課是公開系統原理分類，不控制任何束流或真實設施。","textEn":"This is public system-principle classification, not control of beams or real facilities."}],"quiz":{"question":"「事件紀錄」最主要屬於哪一側？","questionEn":"Which side primarily owns event recording?","options":["探測器與資料取得系統","磁鐵支架的外觀設計","僅真空管的幾何外形"],"optionsEn":["Detector and data-acquisition systems","The visual design of magnet supports","Vacuum-pipe geometry alone"],"answer":0,"explanation":"加速器建立粒子束條件；探測器把相互作用轉為可分析訊號。 本課是公開系統原理分類，不控制任何束流或真實設施。","explanationEn":"Accelerators establish beam conditions; detectors turn interactions into analyzable signals. This is public system-principle classification, not control of beams or real facilities."}},{"id":"d401-v6-02","order":2,"sequence":2,"prerequisiteIds":["d401-v6-01"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-lhc"],"title":"畫出環形束流的介面","titleEn":"Map interfaces around a beam ring","objective":"區分環形路徑、注入連接與碰撞區域。","objectiveEn":"Distinguish ring paths, injection connections and collision regions.","instruction":"畫原創不按比例環圖，標兩方向束流、外部注入來源與碰撞點；所有箭頭標方向。","instructionEn":"Draw an original not-to-scale ring with two beam directions, external injection interfaces and collision points; label every arrow direction.","observation":"一個環形設施仍有多個跨系統的輸入與量測介面。","observationEn":"A ring facility still has multiple cross-system input and measurement interfaces.","failure":"把所有箭頭合併為單一方向，會失去兩束相向運動的意義。","failureEn":"Merging all arrows into one direction loses the meaning of counter-rotating beams.","check":"辨認兩條束流路徑，並明說概念圖不是地下設施地圖。","checkEn":"Identify both beam paths and state that the concept diagram is not a map of underground facilities.","knowledge":[{"id":"d401-v6-02-k1","title":"工程原理","titleEn":"Engineering principle","text":"LHC 的相向束流在分離束管中運行，於指定區域相遇。","textEn":"LHC counter-rotating beams travel in separate beam pipes and meet in designated regions."},{"id":"d401-v6-02-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"不按比例圖用於介面理解，不提供通行、安裝或運轉座標。","textEn":"The not-to-scale map teaches interfaces, not access, installation or operating coordinates."}],"quiz":{"question":"概念環圖必須保留什麼？","questionEn":"What must the conceptual ring retain?","options":["所有地下設備的精確位置","兩束流方向與碰撞介面","把兩束流畫成同一根無方向線"],"optionsEn":["Exact locations of all underground equipment","Both beam directions and collision interfaces","Both beams as one directionless line"],"answer":1,"explanation":"LHC 的相向束流在分離束管中運行，於指定區域相遇。 不按比例圖用於介面理解，不提供通行、安裝或運轉座標。","explanationEn":"LHC counter-rotating beams travel in separate beam pipes and meet in designated regions. The not-to-scale map teaches interfaces, not access, installation or operating coordinates."}},{"id":"d401-v6-03","order":3,"sequence":3,"prerequisiteIds":["d401-v6-02"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-lhc","v6-science-lhc-rf"],"title":"區分單粒子、束團與平均量","titleEn":"Distinguish particles, bunches and averages","objective":"理解離散粒子束與連續平均表示的差別。","objectiveEn":"Understand the difference between discrete bunches and continuous averages.","instruction":"用三群紙點代表三個束團；比較「每群點數」與「整段時間總點數」兩種描述。","instructionEn":"Use three groups of paper dots as bunches; compare dots per bunch with total dots over a time interval.","observation":"相同總點數可以具有不同的時間分布。","observationEn":"Equal total dot counts can have different time distributions.","failure":"把平均量當作每個瞬間都相同，會抹去束團結構。","failureEn":"Treating averages as identical at every instant erases bunch structure.","check":"給每個量附時間窗或束團索引，不加入真實機器設定。","checkEn":"Attach a time window or bunch index to every quantity without using real machine settings.","knowledge":[{"id":"d401-v6-03-k1","title":"工程原理","titleEn":"Engineering principle","text":"束團結構把粒子分布與射頻時間關係連在一起。","textEn":"Bunch structure links particle distributions to RF timing."},{"id":"d401-v6-03-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"紙點不代表真實粒子數、束流強度或操作要求。","textEn":"Paper dots do not represent actual particle counts, beam intensity or operating requirements."}],"quiz":{"question":"相同總點數可否代表相同時間分布？","questionEn":"Do equal total dot counts guarantee identical timing?","options":["可以，總數決定所有時間細節","只有紙的顏色決定時間分布","不能，還需要束團與時間資訊"],"optionsEn":["Yes; the total determines all timing detail","Only paper colour determines timing","No; bunch and timing information is also needed"],"answer":2,"explanation":"束團結構把粒子分布與射頻時間關係連在一起。 紙點不代表真實粒子數、束流強度或操作要求。","explanationEn":"Bunch structure links particle distributions to RF timing. Paper dots do not represent actual particle counts, beam intensity or operating requirements."}},{"id":"d401-v6-04","order":4,"sequence":4,"prerequisiteIds":["d401-v6-03"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-lhc-magnets","v6-science-lhc-rf"],"title":"辨識二極磁鐵的彎轉角色","titleEn":"Identify the bending role of dipole magnets","objective":"把改變方向與增加能量分開。","objectiveEn":"Separate changing direction from adding energy.","instruction":"在概念束流路徑加入二極磁鐵方塊；以相同速度長度的箭頭表示方向改變。","instructionEn":"Add dipole blocks to a conceptual beam path; use equal-length velocity arrows to represent a change of direction.","observation":"理想磁力的彎轉作用不等於射頻電場的加速作用。","observationEn":"Ideal magnetic bending is distinct from acceleration by an RF electric field.","failure":"把彎得更明顯直接當成能量增加，會混淆方向與動能。","failureEn":"Treating greater bending as energy gain confuses direction with kinetic energy.","check":"圖上分別標出方向改變與能量轉移的位置。","checkEn":"Mark direction changes and energy-transfer locations separately.","knowledge":[{"id":"d401-v6-04-k1","title":"工程原理","titleEn":"Engineering principle","text":"磁場可以改變帶電粒子的運動方向，RF 電場用於能量轉移。","textEn":"Magnetic fields can change charged-particle direction, while RF electric fields transfer energy."},{"id":"d401-v6-04-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"示意箭頭不是磁場強度或真實束流調整建議。","textEn":"Diagram arrows are not magnetic-field settings or real beam-adjustment advice."}],"quiz":{"question":"二極磁鐵在本圖的主要作用為何？","questionEn":"What is the dipole’s primary role in this diagram?","options":["彎轉束流方向","記錄碰撞事件的影像","直接替代所有射頻能量輸入"],"optionsEn":["Bending the beam direction","Recording images of collision events","Replacing all RF energy input"],"answer":0,"explanation":"磁場可以改變帶電粒子的運動方向，RF 電場用於能量轉移。 示意箭頭不是磁場強度或真實束流調整建議。","explanationEn":"Magnetic fields can change charged-particle direction, while RF electric fields transfer energy. Diagram arrows are not magnetic-field settings or real beam-adjustment advice."}}]},{"id":"d401-stage02","order":2,"title":"束流支援介面","titleEn":"Beam-support interfaces","description":"理解兩平面聚焦、射頻、熱與真空。","descriptionEn":"Understand two-plane focusing, RF, heat and vacuum.","route":"依學習相依關係閱讀；這四步是公開原理的概念任務，不是現場施工、操作或量產程序。","routeEn":"Follow the learning dependencies. These four tasks explore public principles; they are not field, operating or production procedures.","steps":[{"id":"d401-v6-05","order":1,"sequence":5,"prerequisiteIds":["d401-v6-04"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-lhc-magnets"],"title":"理解四極的兩平面作用","titleEn":"Understand quadrupole action in two planes","objective":"辨識單一四極不能同時簡化為兩方向都聚焦。","objectiveEn":"Recognize that one quadrupole cannot simply be treated as focusing in both planes.","instruction":"畫水平與垂直兩個束流剖面，標同一概念四極在一平面聚焦、另一平面散焦。","instructionEn":"Draw horizontal and vertical beam views, marking conceptual focusing in one plane and defocusing in the other.","observation":"只看一個投影可能誤以為束流已全面收斂。","observationEn":"A single projection can misleadingly suggest convergence in every direction.","failure":"用一個「聚焦」箭頭概括兩平面，會漏掉耦合的設計需求。","failureEn":"One generic focusing arrow hides the need to consider both planes.","check":"成對保存兩平面圖，說明整體磁鐵配置需系統設計。","checkEn":"Keep both plane views and explain that the overall magnet arrangement needs system design.","knowledge":[{"id":"d401-v6-05-k1","title":"工程原理","titleEn":"Engineering principle","text":"四極磁鐵在一個橫向平面聚焦、在另一平面散焦。","textEn":"A quadrupole focuses in one transverse plane and defocuses in the other."},{"id":"d401-v6-05-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"本課不計算機器光學設定或提供磁鐵電流。","textEn":"The lesson does not calculate machine-optics settings or provide magnet currents."}],"quiz":{"question":"只檢查水平束寬的主要缺陷是什麼？","questionEn":"What is the main limitation of checking only horizontal beam width?","options":["無法知道圖紙顏色","可能漏掉垂直平面的散焦","可自動證明兩方向都已最佳化"],"optionsEn":["It does not reveal paper colour","It can miss defocusing in the vertical plane","It automatically proves both directions are optimized"],"answer":1,"explanation":"四極磁鐵在一個橫向平面聚焦、在另一平面散焦。 本課不計算機器光學設定或提供磁鐵電流。","explanationEn":"A quadrupole focuses in one transverse plane and defocuses in the other. The lesson does not calculate machine-optics settings or provide magnet currents."}},{"id":"d401-v6-06","order":2,"sequence":6,"prerequisiteIds":["d401-v6-05"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-lhc-rf"],"title":"用相位圖辨識射頻能量轉移","titleEn":"Identify RF energy transfer with a phase diagram","objective":"理解到達時刻與振盪電場方向的關係。","objectiveEn":"Relate arrival time to the direction of an oscillating electric field.","instruction":"畫正弦概念波與三個到達時刻標記，分辨場方向相同、反向及接近零的區段。","instructionEn":"Draw a conceptual sine wave and three arrival markers, distinguishing same-direction, opposite-direction and near-zero field regions.","observation":"相同位置但不同時刻到達，可能得到不同的能量改變。","observationEn":"Arrival at the same location at different times can produce different energy changes.","failure":"只記共振腔存在就假定所有粒子等量增能，會忽略相位。","failureEn":"Assuming equal energy gain merely because a cavity exists ignores phase.","check":"每個到達點都有時間或相位標籤，結論限於概念方向。","checkEn":"Give each arrival point a time or phase label and limit conclusions to conceptual direction.","knowledge":[{"id":"d401-v6-06-k1","title":"工程原理","titleEn":"Engineering principle","text":"射頻加速取決於粒子通過時的電場相位。","textEn":"RF acceleration depends on electric-field phase when particles pass."},{"id":"d401-v6-06-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"波形不代表 LHC 頻率、相位設定或啟動程序。","textEn":"The waveform does not represent LHC frequency, phase settings or startup procedures."}],"quiz":{"question":"為何相同共振腔可能產生不同能量改變？","questionEn":"Why can the same cavity produce different energy changes?","options":["只因共振腔名字不同","相位與能量轉移完全無關","粒子到達時的電場相位不同"],"optionsEn":["Only because the cavity names differ","Phase has no relation to energy transfer","Particles encounter different electric-field phases"],"answer":2,"explanation":"射頻加速取決於粒子通過時的電場相位。 波形不代表 LHC 頻率、相位設定或啟動程序。","explanationEn":"RF acceleration depends on electric-field phase when particles pass. The waveform does not represent LHC frequency, phase settings or startup procedures."}},{"id":"d401-v6-07","order":3,"sequence":7,"prerequisiteIds":["d401-v6-06"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-lhc","v6-science-lhc-magnets"],"title":"畫出低溫系統的熱路徑","titleEn":"Map heat paths in the cryogenic system","objective":"理解超導設備與環境熱負荷的介面。","objectiveEn":"Understand interfaces between superconducting equipment and environmental heat loads.","instruction":"畫冷端、外殼、支承與電流引入概念方塊，標出可能傳熱路徑及冷卻移除箭頭。","instructionEn":"Draw cold mass, enclosure, support and current-entry blocks, marking possible heat paths and heat-removal arrows.","observation":"機械連接與電氣連接同時可能形成熱路徑。","observationEn":"Mechanical and electrical connections can also form thermal paths.","failure":"只畫冷卻機而不畫熱流入，會讓能量帳看似沒有負荷。","failureEn":"Drawing cooling alone without heat ingress makes the energy account appear load-free.","check":"每條熱流有方向與來源，未知大小不自行填成實測值。","checkEn":"Give every heat flow a direction and origin; do not label unknown magnitudes as measurements.","knowledge":[{"id":"d401-v6-07-k1","title":"工程原理","titleEn":"Engineering principle","text":"低溫工程需管理外部熱流入與內部負荷。","textEn":"Cryogenic engineering must manage external heat ingress and internal loads."},{"id":"d401-v6-07-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"本步不教低溫流體操作、壓力調整或真實超導磁鐵通電。","textEn":"This task does not teach cryogen handling, pressure adjustment or real superconducting-magnet energization."}],"quiz":{"question":"哪個項目應納入低溫概念帳？","questionEn":"Which item belongs in the cryogenic concept account?","options":["支承及電氣介面的熱流入","只有設備名稱","假定所有連接都完全絕熱"],"optionsEn":["Heat ingress through supports and electrical interfaces","Equipment names alone","Assume every connection is perfectly insulating"],"answer":0,"explanation":"低溫工程需管理外部熱流入與內部負荷。 本步不教低溫流體操作、壓力調整或真實超導磁鐵通電。","explanationEn":"Cryogenic engineering must manage external heat ingress and internal loads. This task does not teach cryogen handling, pressure adjustment or real superconducting-magnet energization."}},{"id":"d401-v6-08","order":4,"sequence":8,"prerequisiteIds":["d401-v6-07"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-lhc"],"title":"辨識束管真空的系統角色","titleEn":"Identify the system role of beam-pipe vacuum","objective":"將束流環境與機械連接的要求分開。","objectiveEn":"Separate beam-environment requirements from mechanical connections.","instruction":"在概念束管圖標接頭、量測與抽氣介面；用虛構「資料缺漏」標記說明不能據此判定就緒。","instructionEn":"Mark joints, measurement and pumping interfaces on a concept beam pipe; use a fictional missing-data flag to explain why readiness is unknown.","observation":"機械上連通不等於真空狀態已被確認。","observationEn":"Mechanical continuity does not establish a verified vacuum condition.","failure":"看到圖上管道封閉就宣稱真空合格，會把外觀當量測。","failureEn":"Declaring acceptable vacuum from a closed pipe drawing mistakes appearance for measurement.","check":"區分圖示連接、量測證據與正式授權三種不同欄位。","checkEn":"Separate drawn connectivity, measurement evidence and formal authorization into distinct fields.","knowledge":[{"id":"d401-v6-08-k1","title":"工程原理","titleEn":"Engineering principle","text":"真空環境減少束流與殘餘氣體的相互作用。","textEn":"A vacuum environment reduces interactions between the beam and residual gas."},{"id":"d401-v6-08-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"本課不提供真空門檻、閥件操作或現場排故程序。","textEn":"This lesson provides no vacuum thresholds, valve operations or onsite troubleshooting procedures."}],"quiz":{"question":"封閉束管的示意圖能證明什麼？","questionEn":"What does a closed beam-pipe sketch establish?","options":["所有量測都已通過","概念連接關係，不能證明實際真空品質","可以省略真空監測"],"optionsEn":["All measurements have passed","Conceptual connectivity, not actual vacuum quality","Vacuum monitoring can be omitted"],"answer":1,"explanation":"真空環境減少束流與殘餘氣體的相互作用。 本課不提供真空門檻、閥件操作或現場排故程序。","explanationEn":"A vacuum environment reduces interactions between the beam and residual gas. This lesson provides no vacuum thresholds, valve operations or onsite troubleshooting procedures."}}]},{"id":"d401-stage03","order":3,"title":"狀態證據與科研資料","titleEn":"State evidence and research data","description":"保留未知、版本及選取規則，完成概念交接。","descriptionEn":"Preserve unknowns, versions and selection rules for conceptual handover.","route":"依學習相依關係閱讀；這四步是公開原理的概念任務，不是現場施工、操作或量產程序。","routeEn":"Follow the learning dependencies. These four tasks explore public principles; they are not field, operating or production procedures.","steps":[{"id":"d401-v6-09","order":1,"sequence":9,"prerequisiteIds":["d401-v6-08"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-lhc","v6-science-lhc-magnets"],"title":"把未知狀態保留為未就緒","titleEn":"Keep unknown states as not ready","objective":"區分量測、狀態確認與操作許可。","objectiveEn":"Distinguish measurements, state verification and operating authorization.","instruction":"用紙上表格列真空、低溫、磁鐵與 RF 四列；其中一列資料缺漏，將整體標為待查證。","instructionEn":"Make a paper table for vacuum, cryogenics, magnets and RF; leave one row missing data and mark the overall result unverified.","observation":"其他列正常不能補足缺漏系統的證據。","observationEn":"Normal entries elsewhere cannot substitute for evidence from the missing subsystem.","failure":"把未知狀態當通過會破壞保護與就緒判斷。","failureEn":"Treating unknown as passed undermines protection and readiness assessment.","check":"缺漏欄保留未知，列所需證據與負責角色，不給任何解除或繞過方法。","checkEn":"Preserve unknowns and list required evidence and responsible roles, without release or bypass methods.","knowledge":[{"id":"d401-v6-09-k1","title":"工程原理","titleEn":"Engineering principle","text":"系統就緒需要適用且完整的狀態證據。","textEn":"System readiness requires applicable and complete state evidence."},{"id":"d401-v6-09-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"這是紙上證據分類；真正保護與操作許可由正式系統與授權人員管理。","textEn":"This is paper evidence classification; real protection and authorization remain with formal systems and authorized staff."}],"quiz":{"question":"一個必要欄位資料缺漏時應如何標示？","questionEn":"How should a required field with missing data be marked?","options":["因其他欄正常所以通過","直接停用該檢查","未知／待查證，不視為通過"],"optionsEn":["Passed because other fields look normal","Disable the check","Unknown/unverified, not passed"],"answer":2,"explanation":"系統就緒需要適用且完整的狀態證據。 這是紙上證據分類；真正保護與操作許可由正式系統與授權人員管理。","explanationEn":"System readiness requires applicable and complete state evidence. This is paper evidence classification; real protection and authorization remain with formal systems and authorized staff."}},{"id":"d401-v6-10","order":2,"sequence":10,"prerequisiteIds":["d401-v6-09"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-lhc"],"title":"連接探測器訊號與校正版本","titleEn":"Link detector signals to calibration versions","objective":"使數據可追溯至儀器條件與處理方法。","objectiveEn":"Make data traceable to instrument conditions and processing methods.","instruction":"建立虛構事件卡，包含事件編號、時間標記、探測器子系統、校正版本與原始／處理標籤。","instructionEn":"Create a fictional event card with event ID, timestamp, detector subsystem, calibration version and raw/processed label.","observation":"同一原始訊號經不同校正可能產生不同表示。","observationEn":"Different calibrations can produce different representations of the same raw signal.","failure":"只保存漂亮圖像不保留版本，會阻礙重現與比較。","failureEn":"Keeping only attractive images without versions prevents reproduction and comparison.","check":"每張卡能連回輸入與處理版本，示例不冒充實驗公開事件。","checkEn":"Every card traces back to input and processing version; examples must not masquerade as published experimental events.","knowledge":[{"id":"d401-v6-10-k1","title":"工程原理","titleEn":"Engineering principle","text":"探測器把相互作用轉為電氣或其他可處理訊號，解讀需量測脈絡。","textEn":"Detectors convert interactions into electrical or other processable signals whose interpretation needs measurement context."},{"id":"d401-v6-10-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"這是資料管理概念，沒有提供 LHC 原始事件資料或物理發現證據。","textEn":"This is a data-management concept, not supplied raw LHC event data or evidence of a physics discovery."}],"quiz":{"question":"哪個欄位最有助重現處理結果？","questionEn":"Which field most directly supports reproducing processing results?","options":["校正與處理版本","只記圖片檔名長度","只記展示頁面的背景色"],"optionsEn":["Calibration and processing versions","Image filename length only","Display-page background colour only"],"answer":0,"explanation":"探測器把相互作用轉為電氣或其他可處理訊號，解讀需量測脈絡。 這是資料管理概念，沒有提供 LHC 原始事件資料或物理發現證據。","explanationEn":"Detectors convert interactions into electrical or other processable signals whose interpretation needs measurement context. This is a data-management concept, not supplied raw LHC event data or evidence of a physics discovery."}},{"id":"d401-v6-11","order":3,"sequence":11,"prerequisiteIds":["d401-v6-10"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-lhc"],"title":"分開事件選取與物理結論","titleEn":"Separate event selection from physics conclusions","objective":"避免把可見事件或自設樣本當成發現。","objectiveEn":"Avoid treating visible events or invented samples as discoveries.","instruction":"對十張自行編號的事件卡設定公開的教學選取規則；保留選中與未選中的數量及理由。","instructionEn":"Set an explicit teaching selection rule for ten self-numbered event cards; retain selected and rejected counts and reasons.","observation":"選取規則會改變所看到的樣本，必須揭露。","observationEn":"Selection rules change the observed sample and must be disclosed.","failure":"只展示符合預期的卡片而隱藏規則，會造成選擇偏差。","failureEn":"Showing only expected cards while hiding rules creates selection bias.","check":"列完整起始數、選取條件與剩餘數，聲明不推論新粒子。","checkEn":"Record starting count, selection conditions and remaining count, stating that no new particle is inferred.","knowledge":[{"id":"d401-v6-11-k1","title":"工程原理","titleEn":"Engineering principle","text":"科學結論需要可檢驗方法與充分證據，不能由單一示意事件直接推出。","textEn":"Scientific conclusions require testable methods and sufficient evidence, not a single illustrative event."},{"id":"d401-v6-11-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"教學卡只用來練習透明篩選，沒有實際碰撞量測。","textEn":"Teaching cards practice transparent selection and contain no actual collision measurements."}],"quiz":{"question":"哪個作法可降低選取偏差的隱藏風險？","questionEn":"Which practice reduces hidden selection bias?","options":["只展示最符合期待的一張","公開起始樣本與選取規則","選完後改規則但不記錄"],"optionsEn":["Show only the single most expected card","Disclose the starting sample and selection rules","Change rules afterward without documenting them"],"answer":1,"explanation":"科學結論需要可檢驗方法與充分證據，不能由單一示意事件直接推出。 教學卡只用來練習透明篩選，沒有實際碰撞量測。","explanationEn":"Scientific conclusions require testable methods and sufficient evidence, not a single illustrative event. Teaching cards practice transparent selection and contain no actual collision measurements."}},{"id":"d401-v6-12","order":4,"sequence":12,"prerequisiteIds":["d401-v6-11"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-lhc","v6-science-lhc-magnets","v6-science-lhc-rf"],"title":"完成大型科研系統概念審查","titleEn":"Complete a conceptual review of a large research system","objective":"把束流、支援系統與數據證據整合交接。","objectiveEn":"Integrate beam, support-system and data evidence into a handover.","instruction":"提交責任圖、磁鐵與 RF 概念圖、熱／真空介面表、未就緒清單及事件版本表。","instructionEn":"Submit the responsibility map, magnet and RF concept diagrams, thermal/vacuum interface table, unready-state list and event-version table.","observation":"大型科學設施的可靠性依賴跨系統一致的證據與責任。","observationEn":"Reliability in a large research facility depends on consistent evidence and responsibilities across systems.","failure":"只展示壯觀設備而省略未知與版本，會讓整合無法審查。","failureEn":"Showing impressive equipment while omitting unknowns and versions makes integration unreviewable.","check":"由另一位學徒選一條介面追查來源、假設與責任，保留所有未知項。","checkEn":"Have another learner trace one interface to its sources, assumptions and owner, retaining every unknown.","knowledge":[{"id":"d401-v6-12-k1","title":"工程原理","titleEn":"Engineering principle","text":"系統整合需要功能、介面、證據與授權的清楚區分。","textEn":"System integration needs clear distinctions among functions, interfaces, evidence and authorization."},{"id":"d401-v6-12-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"完成課程不構成粒子加速器設計審查、操作培訓或任何保護系統變更許可。","textEn":"Course completion is not accelerator design approval, operational training or permission to modify protection systems."}],"quiz":{"question":"哪份審查結果最符合本課程？","questionEn":"Which review outcome fits this course?","options":["已獲准實際啟動束流","可以移除任何未通過的保護要求","能說明公共原理與未驗證介面，未聲稱操作授權"],"optionsEn":["It grants permission to start a real beam","It permits removal of unmet protection requirements","It explains public principles and unverified interfaces without claiming operational authorization"],"answer":2,"explanation":"系統整合需要功能、介面、證據與授權的清楚區分。 完成課程不構成粒子加速器設計審查、操作培訓或任何保護系統變更許可。","explanationEn":"System integration needs clear distinctions among functions, interfaces, evidence and authorization. Course completion is not accelerator design approval, operational training or permission to modify protection systems."}}]}],"status":"guided","languageCoverage":["zh-TW","en"],"curriculumVersion":6,"stepCount":12,"estimatedMinutes":240}};
